class Solution {
public:
    vector<int> asteroidCollision(vector<int>& asteroids) {
        vector<int> res;
        for (int a : asteroids) {
            bool alive = true;
            while (alive && a < 0 && !res.empty() && res.back() > 0) {
                if (res.back() < -a) {
                    res.pop_back();
                } else if (res.back() == -a) {
                    res.pop_back();
                    alive = false;
                } else {
                    alive = false;
                }
            }
            if (alive) res.push_back(a);
        }
        return res;
    }
};

class Solution {
    public int[] asteroidCollision(int[] asteroids) {
        int[] st = new int[asteroids.length];
        int top = 0;
        for (int a : asteroids) {
            boolean alive = true;
            while (alive && a < 0 && top > 0 && st[top - 1] > 0) {
                if (st[top - 1] < -a) {
                    top--;
                } else if (st[top - 1] == -a) {
                    top--;
                    alive = false;
                } else {
                    alive = false;
                }
            }
            if (alive) st[top++] = a;
        }
        int[] res = new int[top];
        System.arraycopy(st, 0, res, 0, top);
        return res;
    }
}

var asteroidCollision = function(asteroids) {
    const res = [];
    for (let i = 0; i < asteroids.length; i++) {
        const a = asteroids[i];
        let alive = true;
        while (alive && a < 0 && res.length > 0 && res[res.length - 1] > 0) {
            const top = res[res.length - 1];
            if (top < -a) {
                res.pop();
            } else if (top === -a) {
                res.pop();
                alive = false;
            } else {
                alive = false;
            }
        }
        if (alive) res.push(a);
    }
    return res;
};
